// FreeLang v8 ML — Shape 타입 체커
// 컴파일 타임 shape 오류 검출

export type Shape = (number | string)[];  // string은 심볼릭 차원 (N, M, ...)

export type TensorType = {
  dtype: "f32" | "f64" | "i32";
  shape: Shape;
};

export type ShapeError = {
  message: string;
  line: number;
  col: number;
};

// shape 동일 여부 (심볼릭 포함)
export function shapeEqual(a: Shape, b: Shape): boolean {
  if (a.length !== b.length) return false;
  return a.every((dim, i) => {
    const bd = b[i];
    if (typeof dim === "string" || typeof bd === "string") return true; // 심볼릭은 항상 호환
    return dim === bd;
  });
}

// matmul shape 규칙: [N,M] @ [M,K] → [N,K]
export function matmulShape(a: TensorType, b: TensorType): TensorType | ShapeError {
  if (a.shape.length !== 2 || b.shape.length !== 2) {
    return { message: `matmul: 2D tensor 필요, got [${a.shape}] @ [${b.shape}]`, line: 0, col: 0 };
  }
  const [N, M1] = a.shape;
  const [M2, K] = b.shape;

  // 심볼릭이면 호환으로 간주
  const compatible =
    typeof M1 === "string" || typeof M2 === "string" || M1 === M2;

  if (!compatible) {
    return {
      message: `shape 불일치: [${N},${M1}] @ [${M2},${K}] — 내부 차원 ${M1} ≠ ${M2}`,
      line: 0, col: 0,
    };
  }
  return { dtype: a.dtype, shape: [N, K] };
}

// 원소별 연산 shape 규칙: 동일해야 함
export function elemwiseShape(a: TensorType, b: TensorType): TensorType | ShapeError {
  if (!shapeEqual(a.shape, b.shape)) {
    return {
      message: `shape 불일치: [${a.shape}] vs [${b.shape}]`,
      line: 0, col: 0,
    };
  }
  return { dtype: a.dtype, shape: a.shape };
}

// 전치 shape: [N,M] → [M,N]
export function transposeShape(t: TensorType): TensorType {
  if (t.shape.length !== 2) throw new Error(".T: 2D tensor 필요");
  return { dtype: t.dtype, shape: [t.shape[1], t.shape[0]] };
}

// shape 체커 — 심볼릭 차원 파싱
// "Tensor[3,4]" → { dtype: "f32", shape: [3,4] }
export function parseTensorType(typeStr: string): TensorType | null {
  const m = typeStr.match(/^Tensor\[([^\]]+)\](?:<(\w+)>)?$/);
  if (!m) return null;
  const dims = m[1].split(",").map(s => {
    const n = parseInt(s.trim());
    return isNaN(n) ? s.trim() : n;
  });
  const dtype = (m[2] as "f32" | "f64" | "i32") ?? "f32";
  return { dtype, shape: dims };
}

// 예시 검증 함수
export function checkMatmul(
  aStr: string, bStr: string
): { result: TensorType; error: null } | { result: null; error: ShapeError } {
  const a = parseTensorType(aStr);
  const b = parseTensorType(bStr);
  if (!a) return { result: null, error: { message: `파싱 실패: ${aStr}`, line: 0, col: 0 } };
  if (!b) return { result: null, error: { message: `파싱 실패: ${bStr}`, line: 0, col: 0 } };
  const r = matmulShape(a, b);
  if ("message" in r) return { result: null, error: r };
  return { result: r, error: null };
}

